/**
 * Day 17 — Binary Tree. Original statements + reference solutions for the
 * in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 *
 * Tree input format: one line of space-separated values in level order,
 * "null" marks a missing child; trailing nulls may be omitted. All node
 * values are distinct.
 */

function buildTree(serial) {
  const tokens = serial.trim().split(/\s+/);
  if (!tokens.length || tokens[0] === 'null') return null;
  const root = { val: tokens[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < tokens.length) {
    const node = queue.shift();
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.left = { val: t, left: null, right: null }; queue.push(node.left); }
    }
    if (i < tokens.length) {
      const t = tokens[i++];
      if (t !== 'null') { node.right = { val: t, left: null, right: null }; queue.push(node.right); }
    }
  }
  return root;
}

function inorder(root, out = []) {
  if (!root) return out;
  inorder(root.left, out);
  out.push(root.val);
  inorder(root.right, out);
  return out;
}

function preorder(root, out = []) {
  if (!root) return out;
  out.push(root.val);
  preorder(root.left, out);
  preorder(root.right, out);
  return out;
}

function postorder(root, out = []) {
  if (!root) return out;
  postorder(root.left, out);
  postorder(root.right, out);
  out.push(root.val);
  return out;
}

function levels(root) {
  const rows = [];
  let queue = root ? [root] : [];
  while (queue.length) {
    rows.push(queue);
    const next = [];
    for (const node of queue) {
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    queue = next;
  }
  return rows;
}

const SAMPLE_TREES = [
  '1 2 3 null 4 5 6',
  '1',
  '1 2 null 3',
  '1 2 3 4 5 6 7',
  '1 2 null 3 null 4 null 5',
  '5 3 8 2 4 7 9',
  '1 2 3 4 null null 5 null 6',
  '7 6 5 4 3 null 2',
  '1 2 3 null null 4 5',
  '4 2 6 1 3 5 7',
  '8 3 10 1 6 null 14 null null 4 7 13',
  '10 5 15 3 7 12 20',
  '2 null 3 null 4 null 5',
  '1 null 2 null 3 null 4',
  '9 8 7 6 null 5 4',
];

